INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (36,'2026-07-30T11:18:37+0800','essay_score','deepseek-v4-flash','你是小学生写作教练。基于以下信息给成长型反馈：
