INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (390,'2026-08-11T00:36:16+0800','ai_homework_analyze','deepseek-v4-flash-ga-260731','你是一个只输出JSON的数学应用题分析助手。','以下是数学应用题的句子列表（已按标点切分）。请输出 JSON：
