INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (601,'2026-08-12T19:44:15+0800','ai_chinese_reading','deepseek-v4-flash-ga-260731','你是一个只输出JSON的小学语文教研员。','你是小学语文教研员。下面是一页语文练习/试卷的识别文本。请提取其中所有的【阅读理解】题目（短文阅读大题）。
输出 JSON：{"items":[{"passage":"短文原文（若该题带短文；没有短文则空字符串）","question":"题目完整文本（含所有小题）","type":"题型归类，必须是以下之一：概括主要内容/理解词句/修辞手法/信息提取/字词理解/拓展运用/其他","answer":"参考答案（简短，供讲解使用；拿不准留空）"}]}
