INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (779,'2026-08-12T20:38:02+0800','ai_chinese_essay','deepseek-v4-flash-ga-260731','你是一个只输出JSON的小学作文教研员。','你是小学作文教研员。下面是从三年级上册【同步作文】指导/范文页识别的文本。请提取关键信息：
1) unit：单元（如"第一单元"；从课文/内容推断，不确定填"未分类"）
