INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (1269,'2026-08-13T18:48:51+0800','ai_chinese_highlight','deepseek-v4-flash-ga-260731','你是一个只输出JSON的小学语文老师。','你是小学语文老师。下面是一篇课文/短文。请依据【3】年级语文学习重点，标注值得学习的：
1) words：好词（值得积累的词语/成语，如四字词语、优美动词形容词；需是文中出现的原词）
2) sentences：好句（优美、有修辞、值得仿写或背诵的句子；按文中完整句原文）
